#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="D:\SOMLITS\node_modules\.pnpm\bundlesize@0.18.2_debug@4.4_c66dffdb8e2e32df9dbed59094c521fb\node_modules\bundlesize\node_modules;D:\SOMLITS\node_modules\.pnpm\bundlesize@0.18.2_debug@4.4_c66dffdb8e2e32df9dbed59094c521fb\node_modules;D:\SOMLITS\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/d/SOMLITS/node_modules/.pnpm/bundlesize@0.18.2_debug@4.4_c66dffdb8e2e32df9dbed59094c521fb/node_modules/bundlesize/node_modules:/mnt/d/SOMLITS/node_modules/.pnpm/bundlesize@0.18.2_debug@4.4_c66dffdb8e2e32df9dbed59094c521fb/node_modules:/mnt/d/SOMLITS/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../bundlesize/pipe.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../bundlesize/pipe.js" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../bundlesize/pipe.js" $args
  } else {
    & "node$exe"  "$basedir/../bundlesize/pipe.js" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
